[46061] = {id=46061,name="Adopt a Tadpole",level=1,requiredLevel=1,faction="both",expansion=2,zoneID=9354,mapID=114,description="One day every year, usually in mid-spring, the Winterfin tadpoles are given free reign of the village. I'm not sure why this tradition persists, as it usually results in heavy damage to buildings and food stores. I usually try not to interfere too much with the goings-on of the tribe, but today, I take exception. Go out and see if you can keep an eye on one of the tadpoles.",starts={{npcID=25197,x=0.434,y=0.138,zoneID=3537}},ends={{npcID=118571,x=0.436,y=0.134,zoneID=3537},{npcID=118575,x=0.428,y=0.128,zoneID=3537},{npcID=118577,x=0.434,y=0.136,zoneID=3537},{npcID=118578,x=0.424,y=0.132,zoneID=3537},{npcID=118579,x=0.432,y=0.128,zoneID=3537},{npcID=118580,x=0.424,y=0.132,zoneID=3537},{npcID=118582,x=0.434,y=0.136,zoneID=3537},{npcID=118583,x=0.424,y=0.132,zoneID=3537},{npcID=118584,x=0.436,y=0.134,zoneID=3537},{npcID=118586,x=0.434,y=0.134,zoneID=3537},{npcID=118587,x=0.434,y=0.134,zoneID=3537},{npcID=118589,x=0.434,y=0.134,zoneID=3537},{npcID=118590,x=0.434,y=0.138,zoneID=3537},{npcID=118591,x=0.432,y=0.136,zoneID=3537},{npcID=118592,x=0.428,y=0.134,zoneID=3537},{npcID=118594,x=0.422,y=0.132,zoneID=3537},{npcID=118595,x=0.434,y=0.134,zoneID=3537},{npcID=118596,x=0.434,y=0.138,zoneID=3537},{npcID=118597,x=0.428,y=0.128,zoneID=3537},{npcID=118598,x=0.422,y=0.13,zoneID=3537},{npcID=118599,x=0.422,y=0.134,zoneID=3537},{npcID=118600,x=0.434,y=0.134,zoneID=3537},{npcID=118602,x=0.434,y=0.136,zoneID=3537},{npcID=118603,x=0.436,y=0.136,zoneID=3537}},coords={x=0.434,y=0.138,source="quest_giver",zoneID=3537},questType="world",worldTaskTitle="Adopt a Tadpole"},
[59772] = {id=59772,name="Research Ruination",level=50,requiredLevel=50,faction="both",expansion=2,zoneID=210,mapID=118,description="The Cult of the Damned continue their work within the halls of Aldur'thar. Infiltrate their chambers and destroy their research. It may not stop them, but it will buy us valuable time.",starts={{npcID=170467,x=0.45,y=0.448,zoneID=210}},ends={{npcID=170467,x=0.45,y=0.448,zoneID=210}},coords={x=0.45,y=0.448,source="quest_giver",zoneID=210},questType="world",worldTaskTitle="Research Ruination"},
[59782] = {id=59782,name="The Deathspeaker's Devout",level=50,requiredLevel=50,faction="both",expansion=2,zoneID=210,mapID=118,description="Though Deathspeaker Kharos has long since been slain, the cultists in the nearby mountains continue his nefarious work. Clearly emboldened by the Scourge's resurgence and the rift in the sky, they once again kidnap our crusaders and perform their abhorrent alchemical experiments. Go forth and purge those fanatics from their camp.",starts={{npcID=168880,x=0.66,y=0.22,zoneID=210}},ends={{npcID=168880,x=0.66,y=0.22,zoneID=210}},coords={x=0.66,y=0.22,source="quest_giver",zoneID=210},questType="world",worldTaskTitle="The Deathspeaker's Devout"},
[59783] = {id=59783,name="Cultist Captors",level=50,requiredLevel=50,faction="both",expansion=2,zoneID=210,mapID=118,description="Those damned cultists are relentless! They caught us off guard and managed to drag a few of our crusaders back to their camp. Light only knows what they're doing to them up there... Word is you're quite capable of holding your own. Our numbers are stretched thin enough as it is... if you could rescue the captives, we'd be in your debt. You can find the cultists lurking up in their mountain camp.",starts={{npcID=168880,x=0.66,y=0.22,zoneID=210}},ends={{npcID=168880,x=0.66,y=0.22,zoneID=210}},coords={x=0.66,y=0.22,source="quest_giver",zoneID=210},questType="world",worldTaskTitle="Cultist Captors"},
[59838] = {id=59838,name="Scourge War Machines",level=50,requiredLevel=50,faction="both",expansion=2,zoneID=210,mapID=118,description="The Scourge's war machines make it exceedingly difficult for us to gain ground. They must be our top priority. Though they are well protected, we must destroy them if we are to clear a path for our ground forces and grant them an opportunity to strike. Plant these charges underneath the war machines and then clear the area.",starts={{npcID=170467,x=0.45,y=0.448,zoneID=210}},ends={{npcID=170467,x=0.45,y=0.448,zoneID=210}},coords={x=0.45,y=0.448,source="quest_giver",zoneID=210},questType="world",worldTaskTitle="Scourge War Machines"},
[59847] = {id=59847,name="Defending the Rampart",expansion=2,mapID=118,questType="world",worldTaskTitle="Defending the Rampart"},
[59851] = {id=59851,name="Frozen Solid",level=50,requiredLevel=50,faction="both",expansion=2,zoneID=210,mapID=118,description="The breath of a frost wyrm can freeze even its largest foes in an instant. Our forces, unfortunately, have experienced this firsthand. Their advance toward the citadel has come to a halt. I fear we may lose our foothold unless we act quickly. Take this potion and use it to free our forces from their frigid bonds. Light be with you.",starts={{npcID=170467,x=0.45,y=0.448,zoneID=210}},ends={{npcID=170467,x=0.45,y=0.448,zoneID=210}},coords={x=0.45,y=0.448,source="quest_giver",zoneID=210},questType="world",worldTaskTitle="Frozen Solid"},
[59863] = {id=59863,name="Combat Nullifier 07-X",level=50,requiredLevel=50,faction="both",expansion=2,zoneID=210,mapID=118,description="While everyone is busy fending off our enemies with swords and magic, how about we try something different. Behold, my latest invention--the Combat Nullifier 07-X! With this device, no enemy is truly your enemy any longer! Now, I haven't quite worked out the exact energy modulator calculations, but I am certain it works. Mostly. For now, we'll need to \"borrow\" some energy from our enemies in order to operate it. Go ahead. Charge it up and give it a whirl!",starts={{npcID=173124,x=0.73,y=0.356,zoneID=210}},ends={{npcID=173124,x=0.73,y=0.356,zoneID=210}},coords={x=0.73,y=0.356,source="quest_giver",zoneID=210},questType="world",worldTaskTitle="Combat Nullifier 07-X"},
[59878] = {id=59878,name="Too Many Whelps",level=50,requiredLevel=50,faction="both",expansion=2,zoneID=210,mapID=118,description="We cannot hope to hold this ground if frostwyrms strafe the skies above us. Cultists have been raising whelps from the dead nearby. The more of them we eliminate, the fewer monstrosities to breath deadly ice upon our forces. Put an end to their efforts.",starts={{npcID=167045,x=0.71,y=0.22,zoneID=210}},ends={{npcID=167045,x=0.71,y=0.22,zoneID=210}},coords={x=0.71,y=0.22,source="quest_giver",zoneID=210},questType="world",worldTaskTitle="Too Many Whelps"},
[60841] = {id=60841,name="Evacuation Effort",level=50,requiredLevel=50,faction="both",expansion=2,zoneID=210,mapID=118,description="Our forces are in danger, and the fault is my own. Believing that the surrounding area was safe, I sent a small team to secure the abandoned camp in the valley to the southwest. But our field reports were outdated or mistaken. The camp is a lost cause. We must now focus on rescuing those whom I assigned to it. Head for the camp. Do what you can to save our allies.",starts={{npcID=167045,x=0.71,y=0.22,zoneID=210}},ends={{npcID=167045,x=0.71,y=0.22,zoneID=210}},coords={x=0.71,y=0.22,source="quest_giver",zoneID=210},questType="world",worldTaskTitle="Evacuation Effort"},
[62262] = {id=62262,name="Fungal Feeding",level=50,requiredLevel=50,faction="both",expansion=2,zoneID=210,mapID=118,description="Just as I was making progress on our alternative defense research, my spore samples ran dry! The mushrooms I was using can only be found in a particularly unpleasant location to the southeast. To collect an appropriately sized sample, you'll have to--how do I put this--feed them. Don't ask me why, but apparently, they mature fastest with a nice, rotting corpse nearby. Try luring a few undead to our fungal friends. That should give 'em all the nutrients they need to grow big and strong.",starts={{npcID=167572,x=0.716,y=0.21,zoneID=210}},ends={{npcID=167572,x=0.716,y=0.21,zoneID=210}},coords={x=0.716,y=0.21,source="quest_giver",zoneID=210},questType="world",worldTaskTitle="Fungal Feeding"},
[62295] = {id=62295,name="Cleaning Out the Vault",expansion=2,mapID=118,questType="world",worldTaskTitle="Cleaning Out the Vault"},
[62365] = {id=62365,name="Careful Creations",level=50,requiredLevel=50,faction="both",expansion=2,zoneID=210,mapID=118,description="What better way to stop our enemies in their tracks than to use their own experiments against them? Lucky for us, some of our... friends have left a few samples unattended. And I know just where to test it... As menacing as they may be, those abominations down there are delicate creations. It would be a shame if you were to get your hands on some of their equipment and disrupt the process...",starts={{npcID=173997,x=0.354,y=0.664,zoneID=210}},ends={{npcID=173997,x=0.354,y=0.664,zoneID=210}},coords={x=0.354,y=0.664,source="quest_giver",zoneID=210},questType="world",worldTaskTitle="Careful Creations"},
[62473] = {id=62473,name="What's Old is New",level=50,requiredLevel=50,faction="both",expansion=2,zoneID=210,mapID=118,description="These damn Scourge make me sick! They're only good fer one thing--bein' dead! Head tae the valley southwest o' here. Plenty o' gear fer the pickin' over there! Gather up what ye can. I'll make do with what ye find.",starts={{npcID=167577,x=0.72,y=0.206,zoneID=210}},ends={{npcID=167577,x=0.72,y=0.206,zoneID=210}},coords={x=0.72,y=0.206,source="quest_giver",zoneID=210},questType="world",worldTaskTitle="What's Old is New"},
[62484] = {id=62484,name="Werk In Progress",level=50,requiredLevel=50,faction="both",expansion=2,zoneID=210,mapID=118,description="We received an... unusual delivery recently. I'm still in a bit of shock. Some sort of flying contraption released a huge crate just overhead, parachute and all. If it weren't for the wind it would have landed nearby. Instead, it drifted down the hill below. They left a note too. It would have been lost had it not been wrapped around a sizeable rock. Darkrider Arly massages a spot on her forehead.> I don't know what it is, but if it'll help clear out the area, I'm all for it.",starts={{npcID=173997,x=0.354,y=0.664,zoneID=210}},ends={{npcID=173997,x=0.354,y=0.664,zoneID=210}},coords={x=0.354,y=0.664,source="quest_giver",zoneID=210},questType="world",worldTaskTitle="Werk In Progress"},
[62553] = {id=62553,name="Delaying Their Efforts",level=50,requiredLevel=50,faction="both",expansion=2,zoneID=210,mapID=118,description="The Scourge continue to replenish their weapons of war from blighted grounds. Stopping their workers slows their production, but a decisive blow to their stockpiles would be far more effective. Take these and head to the area southeast of here. Plant the bombs, then make a quick exit. Weakening their supply lines should provide us ample time to retaliate.",starts={{npcID=167045,x=0.71,y=0.22,zoneID=210}},ends={{npcID=167045,x=0.71,y=0.22,zoneID=210}},coords={x=0.71,y=0.22,source="quest_giver",zoneID=210},questType="world",worldTaskTitle="Delaying Their Efforts"},
[62584] = {id=62584,name="Frontline Resupply",level=50,requiredLevel=50,faction="both",expansion=2,zoneID=210,mapID=118,description="This forward camp relies heavily on our supply line from the tournament grounds. A recent shipment was attacked while in transit through the valley below us. Salvage what you can, and if possible, eliminate the threat so this does not happen again.",starts={{npcID=170467,x=0.45,y=0.448,zoneID=210}},ends={{npcID=170467,x=0.45,y=0.448,zoneID=210}},coords={x=0.45,y=0.448,source="quest_giver",zoneID=210},questType="world",worldTaskTitle="Frontline Resupply"},
}
end)
